#!/usr/bin/env python3\n# Comprehensive NLP Project Demo\n# Demonstrates all implemented features for comparative study\n\nimport os\nimport sys\nfrom datetime import datetime\n\n# Add project root to path for imports\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\ntry:\n    from test import summarize_meeting, structured_summarization_pipeline, summarize_text\n    from qa_system import QuestionAnsweringSystem\n    from evaluation_metrics import EvaluationMetrics\n    from dataset_handler import DatasetHandler\n    MODULES_AVAILABLE = True\nexcept ImportError as e:\n    print(f\"[!] Could not import modules: {e}\")\n    print(\"[*] Make sure all dependencies are installed with: pip install -r requirements.txt\")\n    MODULES_AVAILABLE = False\n\ndef run_video_processing_demo(video_path=\"video.mp4\"):\n    \"\"\"\n    Demonstrate video processing with both structured and unstructured methods\n    \"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"VIDEO PROCESSING DEMONSTRATION\")\n    print(\"=\"*60)\n    \n    if not os.path.exists(video_path):\n        print(f\"[!] Video file not found: {video_path}\")\n        print(\"[*] Please ensure you have a video file in the project directory\")\n        return False\n    \n    try:\n        print(f\"[*] Processing video: {video_path}\")\n        summarize_meeting(video_path)\n        print(\"[✓] Video processing completed!\")\n        return True\n    except Exception as e:\n        print(f\"[!] Video processing failed: {e}\")\n        return False\n\ndef run_qa_system_demo():\n    \"\"\"\n    Demonstrate the Question-Answering system\n    \"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"QUESTION-ANSWERING SYSTEM DEMONSTRATION\")\n    print(\"=\"*60)\n    \n    # Sample context (could be from video transcript)\n    sample_context = \"\"\"\n    This is a meeting transcript about project planning and budget allocation.\n    John Smith, the project manager, discussed the timeline for the new software development project.\n    The project is scheduled to start on January 15th and should be completed by June 30th.\n    Sarah Johnson from the finance department mentioned that the allocated budget is $250,000.\n    The development team will consist of 5 engineers and 2 designers.\n    Testing phase is planned to begin in May, with user acceptance testing in early June.\n    Marketing campaigns will launch after the product release, targeting both B2B and B2C segments.\n    Risk assessment identified potential delays in the third-party API integration.\n    \"\"\"\n    \n    qa_system = QuestionAnsweringSystem()\n    qa_system.set_context(sample_context)\n    \n    test_questions = [\n        \"What is the project timeline?\",\n        \"Who is the project manager?\",\n        \"What is the allocated budget?\",\n        \"When will testing begin?\",\n        \"What are the main risks identified?\"\n    ]\n    \n    print(f\"Context: {sample_context[:100]}...\")\n    print(f\"\\nContext Statistics: {qa_system.get_context_summary()}\")\n    \n    for question in test_questions:\n        print(f\"\\n📋 Question: {question}\")\n        \n        # Test both methods\n        results = qa_system.answer_question(question, method=\"both\")\n        \n        if 'structured' in results:\n            print(f\"🔧 Structured Answer: {results['structured']['answer']}\")\n            print(f\"   Confidence: {results['structured']['confidence']:.3f}\")\n        \n        if 'unstructured' in results:\n            print(f\"🧠 Unstructured Answer: {results['unstructured']['answer']}\")\n            print(f\"   Confidence: {results['unstructured']['confidence']:.3f}\")\n        \n        if 'comparison' in results:\n            recommended = results['comparison']['recommended_method']\n            print(f\"   💡 Recommended method: {recommended}\")\n\ndef run_comparative_evaluation_demo():\n    \"\"\"\n    Demonstrate comparative evaluation of structured vs unstructured methods\n    \"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"COMPARATIVE EVALUATION DEMONSTRATION\")\n    print(\"=\"*60)\n    \n    # Sample text for evaluation\n    sample_text = \"\"\"\n    Artificial Intelligence has revolutionized numerous industries in recent years. \n    Machine learning algorithms now power recommendation systems, autonomous vehicles, \n    and medical diagnosis tools. Natural Language Processing enables chatbots and \n    translation services to understand and generate human-like text. Computer vision \n    applications help in facial recognition, object detection, and medical imaging analysis.\n    \n    The rapid advancement in AI technology has also raised important ethical considerations. \n    Issues such as algorithmic bias, privacy concerns, and job displacement need careful \n    attention from researchers and policymakers. Companies are investing heavily in \n    responsible AI development to ensure these technologies benefit society as a whole.\n    \n    Future developments in AI include quantum computing integration, neuromorphic \n    computing, and advanced neural network architectures. These innovations promise \n    to unlock even greater capabilities while addressing current limitations in \n    energy efficiency and computational requirements.\n    \"\"\"\n    \n    evaluator = EvaluationMetrics()\n    \n    print(\"[*] Running comparative evaluation...\")\n    \n    # Run comparative evaluation\n    try:\n        results = evaluator.comparative_evaluation(\n            sample_text,\n            structured_summarization_pipeline,\n            summarize_text\n        )\n        \n        print(\"\\n📊 EVALUATION RESULTS:\")\n        print(\"-\" * 40)\n        \n        # Performance metrics\n        print(\"⏱️  PERFORMANCE METRICS:\")\n        print(f\"   Structured processing time: {results['structured']['processing_time']:.3f}s\")\n        print(f\"   Unstructured processing time: {results['unstructured']['processing_time']:.3f}s\")\n        print(f\"   Speed advantage: {results['comparison']['faster_method']} method\")\n        \n        # Memory usage\n        print(f\"\\n💾 MEMORY USAGE:\")\n        print(f\"   Structured memory: {results['structured']['memory_used']:.2f} MB\")\n        print(f\"   Unstructured memory: {results['unstructured']['memory_used']:.2f} MB\")\n        print(f\"   Memory efficiency: {results['comparison']['more_efficient_memory']} method\")\n        \n        # Quality metrics\n        print(f\"\\n📝 QUALITY METRICS:\")\n        print(\"   Structured approach:\")\n        for metric, value in results['structured']['quality_metrics'].items():\n            if metric != 'error':\n                print(f\"     {metric}: {value}\")\n        \n        print(\"   Unstructured approach:\")\n        for metric, value in results['unstructured']['quality_metrics'].items():\n            if metric != 'error':\n                print(f\"     {metric}: {value}\")\n        \n        # Generate detailed report\n        report_filename = f\"evaluation_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt\"\n        evaluator.generate_evaluation_report(results, report_filename)\n        print(f\"\\n📄 Detailed report saved to: {report_filename}\")\n        \n        return results\n        \n    except Exception as e:\n        print(f\"[!] Evaluation failed: {e}\")\n        return None\n\ndef run_dataset_demo():\n    \"\"\"\n    Demonstrate dataset handling capabilities\n    \"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"DATASET HANDLING DEMONSTRATION\")\n    print(\"=\"*60)\n    \n    handler = DatasetHandler()\n    \n    # Show supported datasets\n    print(\"📚 SUPPORTED DATASETS:\")\n    dataset_info = handler.get_dataset_info()\n    for name, info in dataset_info.items():\n        status = \"✓ Available\" if info['loaded'] else \"✗ Not loaded\"\n        print(f\"   {name}: {info['description']} - {status}\")\n    \n    # Try to load some datasets\n    print(\"\\n[*] Attempting to load benchmark datasets...\")\n    try:\n        load_results = handler.load_benchmark_datasets(sample_size=5)\n        \n        loaded_count = sum(1 for success in load_results.values() if success)\n        print(f\"[✓] Successfully loaded {loaded_count}/{len(load_results)} datasets\")\n        \n        # Show previews of loaded datasets\n        for dataset_name, success in load_results.items():\n            if success:\n                print(f\"\\n📋 Preview of {dataset_name}:\")\n                previews = handler.get_sample_preview(dataset_name, num_samples=1)\n                if previews:\n                    preview = previews[0]\n                    print(f\"   Task: {preview.get('task', 'Unknown')}\")\n                    print(f\"   Input: {preview.get('input_text', 'N/A')}\")\n                    if 'reference_summary' in preview:\n                        print(f\"   Reference: {preview['reference_summary']}\")\n    \n    except Exception as e:\n        print(f\"[!] Dataset loading failed: {e}\")\n    \n    # Demonstrate custom evaluation set creation\n    print(\"\\n[*] Creating custom evaluation set...\")\n    custom_texts = [\n        \"This is a sample document about machine learning and its applications in various industries.\",\n        \"Natural language processing has become increasingly important for automated text analysis.\"\n    ]\n    \n    custom_summaries = [\n        \"Machine learning applications in industries.\",\n        \"NLP importance in automated text analysis.\"\n    ]\n    \n    custom_samples = handler.create_custom_evaluation_set(custom_texts, custom_summaries)\n    print(f\"[✓] Created {len(custom_samples)} custom evaluation samples\")\n    \n    # Save and load demonstration\n    if handler.save_evaluation_set(custom_samples, \"demo_evaluation.json\"):\n        loaded_samples = handler.load_evaluation_set(\"demo_evaluation.json\")\n        print(f\"[✓] Saved and loaded {len(loaded_samples)} evaluation samples\")\n\ndef run_full_pipeline_demo():\n    \"\"\"\n    Demonstrate the complete pipeline integration\n    \"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"COMPLETE PIPELINE DEMONSTRATION\")\n    print(\"=\"*60)\n    \n    # Sample transcript (as if from video processing)\n    sample_transcript = \"\"\"\n    [00:00:15] Welcome everyone to today's quarterly business review meeting. I'm Sarah Chen, the VP of Operations.\n    [00:00:45] Today we'll be discussing our Q3 performance metrics, upcoming product launches, and budget allocation for Q4.\n    [00:01:20] John from the sales team will present our revenue figures, which show a 23% increase compared to last quarter.\n    [00:02:10] The marketing campaign for our new mobile app generated over 50,000 downloads in the first week alone.\n    [00:03:00] Our customer satisfaction scores have improved to 4.7 out of 5, thanks to the enhanced customer support system.\n    [00:03:45] Looking ahead, we're planning to launch three new features: advanced analytics, real-time collaboration, and AI-powered recommendations.\n    [00:04:30] The development team estimates these features will be ready for beta testing by December 1st.\n    [00:05:15] For Q4, we're allocating $500,000 for marketing, $300,000 for R&D, and $200,000 for customer acquisition.\n    [00:06:00] Any questions about the roadmap or budget allocation? We have 15 minutes for discussion.\n    \"\"\"\n    \n    print(\"[*] Processing sample meeting transcript...\")\n    \n    # 1. Generate both types of summaries\n    print(\"\\n🔄 STEP 1: Generating summaries using both approaches\")\n    \n    try:\n        # Structured summary\n        structured_results = structured_summarization_pipeline(sample_transcript)\n        print(f\"[✓] Structured analysis completed\")\n        print(f\"   - Extractive summary: {len(structured_results['extractive_summary'])} characters\")\n        print(f\"   - Entities found: {len(structured_results['entities'])}\")\n        print(f\"   - Topics identified: {len(structured_results['topics'])}\")\n        \n        # Unstructured summary\n        abstractive_summary = summarize_text(sample_transcript)\n        print(f\"[✓] Abstractive summary generated: {len(abstractive_summary)} characters\")\n        \n    except Exception as e:\n        print(f\"[!] Summary generation failed: {e}\")\n        return False\n    \n    # 2. Set up Q&A system\n    print(\"\\n❓ STEP 2: Setting up Q&A system\")\n    qa_system = QuestionAnsweringSystem()\n    qa_system.set_context(sample_transcript)\n    \n    # 3. Answer sample questions\n    business_questions = [\n        \"What was the revenue increase percentage?\",\n        \"How many app downloads were generated?\",\n        \"What is the customer satisfaction score?\",\n        \"When will beta testing begin?\",\n        \"What is the total Q4 budget allocation?\"\n    ]\n    \n    print(\"\\n🤖 STEP 3: Answering business questions\")\n    for question in business_questions:\n        try:\n            results = qa_system.answer_question(question, method=\"both\")\n            print(f\"\\nQ: {question}\")\n            \n            if 'structured' in results and 'unstructured' in results:\n                s_conf = results['structured']['confidence']\n                u_conf = results['unstructured']['confidence']\n                \n                if s_conf > u_conf:\n                    print(f\"A: {results['structured']['answer']} (structured method, confidence: {s_conf:.3f})\")\n                else:\n                    print(f\"A: {results['unstructured']['answer']} (unstructured method, confidence: {u_conf:.3f})\")\n            \n        except Exception as e:\n            print(f\"   Error: {e}\")\n    \n    # 4. Run evaluation\n    print(\"\\n📊 STEP 4: Running performance evaluation\")\n    try:\n        evaluator = EvaluationMetrics()\n        eval_results = evaluator.comparative_evaluation(\n            sample_transcript,\n            structured_summarization_pipeline,\n            summarize_text\n        )\n        \n        print(f\"[✓] Evaluation completed\")\n        print(f\"   - Faster method: {eval_results['comparison']['faster_method']}\")\n        print(f\"   - More memory efficient: {eval_results['comparison']['more_efficient_memory']}\")\n        \n    except Exception as e:\n        print(f\"[!] Evaluation failed: {e}\")\n    \n    # 5. Save complete results\n    print(\"\\n💾 STEP 5: Saving complete analysis\")\n    output_filename = f\"complete_analysis_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt\"\n    \n    try:\n        with open(output_filename, 'w', encoding='utf-8') as f:\n            f.write(\"=== COMPLETE NLP ANALYSIS REPORT ===\\n\\n\")\n            f.write(f\"Generated on: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\\n\\n\")\n            \n            f.write(\"=== ORIGINAL TRANSCRIPT ===\\n\")\n            f.write(sample_transcript + \"\\n\\n\")\n            \n            f.write(\"=== ABSTRACTIVE SUMMARY (BART) ===\\n\")\n            f.write(abstractive_summary + \"\\n\\n\")\n            \n            f.write(\"=== EXTRACTIVE SUMMARY (TextRank) ===\\n\")\n            f.write(structured_results['extractive_summary'] + \"\\n\\n\")\n            \n            f.write(\"=== NAMED ENTITIES ===\\n\")\n            for entity, label in structured_results['entities']:\n                f.write(f\"{entity} ({label})\\n\")\n            \n            f.write(\"\\n=== TOPICS (LDA) ===\\n\")\n            for i, topic in enumerate(structured_results['topics']):\n                f.write(f\"Topic {i+1}: {topic[1]}\\n\")\n            \n            f.write(\"\\n=== Q&A EXAMPLES ===\\n\")\n            for question in business_questions[:3]:  # Save first 3 Q&As\n                f.write(f\"Q: {question}\\n\")\n                try:\n                    result = qa_system.answer_question(question, method=\"structured\")\n                    if 'structured' in result:\n                        f.write(f\"A: {result['structured']['answer']}\\n\\n\")\n                except:\n                    f.write(\"A: [Error processing question]\\n\\n\")\n        \n        print(f\"[✓] Complete analysis saved to: {output_filename}\")\n        \n    except Exception as e:\n        print(f\"[!] Failed to save analysis: {e}\")\n    \n    return True\n\ndef main():\n    \"\"\"\n    Main demonstration function\n    \"\"\"\n    print(\"🚀 NLP PROJECT COMPREHENSIVE DEMONSTRATION\")\n    print(\"Comparative Study of Structured and Unstructured NLP Models\")\n    print(\"=\"*80)\n    \n    if not MODULES_AVAILABLE:\n        print(\"[!] Required modules not available. Please install dependencies first.\")\n        print(\"    pip install -r requirements.txt\")\n        print(\"    python -m spacy download en_core_web_sm\")\n        return False\n    \n    demos = [\n        (\"Dataset Handling\", run_dataset_demo),\n        (\"Q&A System\", run_qa_system_demo),\n        (\"Comparative Evaluation\", run_comparative_evaluation_demo),\n        (\"Complete Pipeline\", run_full_pipeline_demo),\n    ]\n    \n    # Ask user which demos to run\n    print(\"\\nAvailable demonstrations:\")\n    for i, (name, _) in enumerate(demos, 1):\n        print(f\"  {i}. {name}\")\n    print(f\"  {len(demos)+1}. Run all demonstrations\")\n    print(f\"  {len(demos)+2}. Video processing (requires video file)\")\n    \n    try:\n        choice = input(\"\\nSelect demonstration (1-{0}): \".format(len(demos)+2))\n        choice = int(choice)\n        \n        if choice == len(demos) + 1:  # Run all\n            print(\"\\n[*] Running all demonstrations...\")\n            for name, demo_func in demos:\n                print(f\"\\n🎯 Running {name} demonstration...\")\n                try:\n                    demo_func()\n                except Exception as e:\n                    print(f\"[!] Demo failed: {e}\")\n        \n        elif choice == len(demos) + 2:  # Video processing\n            video_file = input(\"Enter video file path (or press Enter for 'video.mp4'): \").strip()\n            if not video_file:\n                video_file = \"video.mp4\"\n            run_video_processing_demo(video_file)\n        \n        elif 1 <= choice <= len(demos):\n            name, demo_func = demos[choice - 1]\n            print(f\"\\n🎯 Running {name} demonstration...\")\n            demo_func()\n        \n        else:\n            print(\"Invalid choice. Exiting.\")\n            return False\n    \n    except (ValueError, KeyboardInterrupt):\n        print(\"\\nExiting demonstration.\")\n        return False\n    \n    print(\"\\n\" + \"=\"*80)\n    print(\"🎉 DEMONSTRATION COMPLETED SUCCESSFULLY!\")\n    print(\"\\nYour NLP project now includes:\")\n    print(\"✓ Video transcription with OpenAI Whisper\")\n    print(\"✓ Structured NLP (TF-IDF, TextRank, LDA, NER)\")\n    print(\"✓ Unstructured NLP (BART, T5, transformers)\")\n    print(\"✓ Dual-approach Question-Answering system\")\n    print(\"✓ Comprehensive evaluation metrics (ROUGE, BLEU)\")\n    print(\"✓ Dataset handling for benchmarking\")\n    print(\"✓ Enhanced GUI with comparison features\")\n    print(\"✓ Performance monitoring and reporting\")\n    print(\"\\nAll features are integrated and ready for your project presentation!\")\n    print(\"=\"*80)\n    \n    return True\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except KeyboardInterrupt:\n        print(\"\\n\\n[*] Demonstration interrupted by user.\")\n    except Exception as e:\n        print(f\"\\n\\n[!] Demonstration failed with error: {e}\")\n        print(\"Please check your installation and try again.\")\n